code.cpp:
class CustomFunction {
public:
    int f(int x, int y);
};

class Solution {
public:
    vector<vector<int>> findSolution(CustomFunction& customfunction, int z) {
        vector<vector<int>> result;
        int x = 1, y = 1000;
        while (x <= 1000 && y >= 1) {
            int v = customfunction.f(x, y);
            if (v == z) {
                result.push_back({x, y});
                ++x;
            } else if (v < z) {
                ++x;
            } else {
                --y;
            }
        }
        return result;
    }
};
